<script setup lang="ts">import {ref,onMounted} from 'vue';import {getFollowing,unfollowPlatform} from '../api';import type {FederationPlatform} from '../types';import {RouterLink} from 'vue-router';import {Network,Users,FileText,Minus} from 'lucide-vue-next';const platforms=ref<FederationPlatform[]>([]);const loading=ref(true);async function load(){loading.value=true;platforms.value=await getFollowing();loading.value=false}onMounted(load);async function unfollow(p:FederationPlatform){await unfollowPlatform(p.id);await load()}</script>
<template><div class="page"><div class="center wide"><div class="eyebrow">Minha rede</div><h1>Plataformas que sigo</h1><p class="lead">As publicações dessas plataformas aparecem automaticamente no seu feed.</p><div v-if="loading" class="card" style="margin-top:25px">Carregando…</div><div v-else-if="!platforms.length" class="card empty-box" style="margin-top:25px"><Network :size="28"/><strong>Você ainda não segue nenhuma plataforma.</strong><RouterLink class="btn primary" to="/federation">Descobrir plataformas</RouterLink></div><div v-else class="following-list"><article v-for="p in platforms" :key="p.id" class="card following-card"><div class="platform-logo">{{p.name.slice(0,1)}}</div><div class="following-info"><RouterLink :to="`/federation/${p.id}`"><h3>{{p.name}}</h3></RouterLink><span class="handle">{{p.handle}}</span><p>{{p.description}}</p><div class="platform-stats"><span><FileText :size="14"/> {{p.resourcesCount}} recursos</span><span><Users :size="14"/> {{p.followersCount}} seguidores</span></div></div><button class="btn ghost" @click="unfollow(p)"><Minus :size="15"/> Deixar de seguir</button></article></div></div></div></template>
